const assert = require('node:assert/strict');
const fs = require('node:fs');
const cp = require('node:child_process');
const yaml = require('yaml');
const B = '7bae1f87cb8d6a708b7c4de0b990e82e5a503369';
const branch = 'fix/ui044-correcoes-finais-20261105';
const original = (path) => cp.execFileSync('git',['show',B+':'+path],{encoding:'utf8'});
const vBase = JSON.parse(original('vercel.json'));
const vNow = JSON.parse(fs.readFileSync('vercel.json','utf8'));
assert.equal(vNow.git.deploymentEnabled[branch],false);
delete vNow.git.deploymentEnabled[branch];
assert.deepEqual(vNow,vBase);
const wBase = yaml.parse(original('.github/workflows/rc-review.yml'));
const wNow = yaml.parse(fs.readFileSync('.github/workflows/rc-review.yml','utf8'));
assert.equal(wNow.on.push.branches.filter(x=>x===branch).length,1);
wNow.on.push.branches=wNow.on.push.branches.filter(x=>x!==branch);
const suffix=" || github.ref_name == '"+branch+"'";
const flatten=s=>s.trim().replace(/\s+/g,' ');
assert.ok(flatten(wNow.jobs.validate.if).endsWith(suffix));
assert.equal(flatten(wNow.jobs.validate.if).slice(0,-suffix.length),flatten(wBase.jobs.validate.if));
wNow.jobs.validate.if=wBase.jobs.validate.if;
assert.deepEqual(wNow,wBase);
console.log('PASS exact Vercel false entry; PASS exact RC push/if addition; all other configuration values unchanged');
